/// <summary>
/// class <c>METTelemetryPOApprovalErrorEvent</c> is used to log error event whenever purchase order creation info event.
/// </summary>
internal final class METTelemetryPOApprovalErrorEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetryPOApprovalErrorEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetryPOApprovalErrorEvent</c> </returns>
public static METTelemetryPOApprovalErrorEvent construct()
{
    return new METTelemetryPOApprovalErrorEvent();
}

/// <summary>
/// Run error event
/// </summary>
/// <param name = "_purchTable"> purchase table <c>PurchTable</c> </param>
/// <param name = "_error"> error message </param>
public static void runTelemetryEvent(PurchTable _purchTable, str _error)
{
    METTelemetryPOApprovalErrorEvent poApprovalEvent = METTelemetryPOApprovalErrorEvent::construct();

    poApprovalEvent.addRunTimePropertyToAppinsights(_purchTable,_error);

    poApprovalEvent.processEvent(METTelemetryEventNames::POApprovalErrorEvent);
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_purchTable"> table <c>_purchTable</c> </param>
/// <param name = "_error"> error message </param>
public void addRunTimePropertyToAppinsights(PurchTable _purchTable, str _error)
{
    this.addRuntimeProperty('PurchaseOrderId', _purchTable.PurchId);
    this.addRuntimeProperty('warehouseId' ,_purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', _purchTable.VendorRef);
    this.addRuntimeProperty('VendorAccount', _purchTable.OrderAccount);
    this.addRuntimeProperty('VendorAccount', _purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', _purchTable.VendorRef);
    this.addRuntimeProperty('BuyerGroup', _purchTable.ItemBuyerGroupId);
    this.addRuntimeProperty('Message', _error);
}
